questionvariables.text:
/*Part (a) of the question*/
motorists:rand(300)+250; /*Total number of motorists*/
female_motorists:rand(100)+100; /*number of female motorist*/
male_motorists:motorists-female_motorists; /*total number of male motorists*/

v_power:rand(50)+10 ; /*total number of motorist buying v_power*/
female_v:rand_with_step(10,v_power,10); /*female motorist buying v_power*/
male_v:v_power-female_v; /*male motorist buying v_power*/

diesel_fuel:rand(50)+40; /*total number of motorist buying diesel*/
male_diesel:rand_with_step(10,diesel_fuel,10); /*male motorist buying diesel*/
female_diesel:diesel_fuel-male_diesel;/*female motorist buying diesel*/

super_fuel:motorists-(v_power+diesel_fuel);/*total number of motorist buying super fuel*/
male_super_fuel: male_motorists-(male_v+male_diesel); /*male motorist buying super fuel*/
female_super_fuel: female_motorists-(female_v+female_diesel); /*female motorist buying super fuel*/
/*model answers for part a*/
ta1:decimalplaces(super_fuel/motorists,2); /*Probability motorist buys super fuel*/
ta2: decimalplaces((male_super_fuel/motorists)/(super_fuel/motorists),2) ;/*Probability motorist is male given he buys super fuel*/
/*Part b of the question*/
v_power_car_servived:rand_with_step(5,20,2);
super_fuel_car_servived:rand_with_step(5,20,3);
diesel_fuel_car_servived:rand_with_step(5,20,4);
car_serviced: decimalplaces(((v_power_car_servived*v_power)/100)+((super_fuel_car_servived*super_fuel)/100)+ ((diesel_fuel_car_servived*diesel_fuel)/100) ,2);
ta3:decimalplaces(car_serviced/motorists,2); /*probability motorist has his or her car serviced by the garage*/
ta4: decimalplaces(((diesel_fuel_car_servived*diesel_fuel)/100)/(car_serviced),2);  /*Probability that the motorist buys diesel fuel given his or her car is serviced*/

